"""Compact, offline charts derived only from selected frozen report records."""

CHART_LOGIC = r"""
  function chartData(state){
    const selected=select(state),summary=summarize(state),execution=new Map(),ratings=new Map(),comparisons=new Map();
    for(const trial of selected.trials){
      const row=execution.get(trial.arm)||{arm:trial.arm,trials:0,status_counts:{},observed_turns:0,planned:[]};
      row.trials++;row.status_counts[trial.status]=(row.status_counts[trial.status]||0)+1;row.observed_turns+=observed(trial);row.planned.push(planned(trial));execution.set(trial.arm,row);
    }
    for(const rating of selected.ratings){const row=ratings.get(rating.cohort_id)||{cohort_id:rating.cohort_id,case_id:value(rating,'case_id'),arm:value(rating,'skill'),records:[]};row.records.push(rating);ratings.set(rating.cohort_id,row);}
    for(const pair of compare(state).rows){const key=pair.case_fingerprint||pair.case_id,row=comparisons.get(key)||{case_id:pair.case_id,case_fingerprint:key,counts:{win:0,tie:0,loss:0,undetermined:0},pairs:0};row.counts[pair.outcome in row.counts?pair.outcome:'undetermined']++;row.pairs++;comparisons.set(key,row);}
    return {execution:[...execution.values()].map(({planned,...row})=>({...row,planned_turns:totalKnown(planned)})),ratings:[...ratings.values()].map(({records,...row})=>({...row,rating_rows:records.length,score_counts:countScores(records)})),comparisons:[...comparisons.values()],tokens:['input_tokens','cached_input_tokens','uncached_input_tokens','output_tokens'].map(field=>({field,...summary.usage[field],value:summary.usage[field].known?summary.usage[field].subtotal:null}))};
  }
  function ratingTrend(rows){
    const points=rows.map((row,index)=>({index,value:row.rating_rows?100*(row.rating_rows-row.score_counts.unverifiable)/row.rating_rows:null}));
    return {points,maximum:100,connections:points.flatMap((point,index)=>index&&point.value!==null&&points[index-1].value!==null?[[index-1,index]]:[])};
  }
  function countScale(value){
    const target=Math.max(1,value)/4,magnitude=10**Math.floor(Math.log10(target)),step=Math.max(1,[1,2,5,10].find(n=>n*magnitude>=target)*magnitude),maximum=Math.max(step,Math.ceil(value/step)*step);
    return {maximum,ticks:Array.from({length:Math.round(maximum/step)+1},(_,index)=>index*step)};
  }
"""

