CHART_SCRIPT = r"""
function benchSvg(tag,attrs={},text){const element=document.createElementNS('http://www.w3.org/2000/svg',tag);for(const [key,value] of Object.entries(attrs))element.setAttribute(key,String(value));if(text!==undefined)element.textContent=String(text);return element;}
const ratingCategories=['0','1','2','unverifiable'].map(key=>({key,label:scoreLabel(key),color:key==='unverifiable'?'#875015':scoreColor(key)}));
const comparisonCategories=['win','tie','loss','undetermined'].map(key=>({key,label:outcomeLabel(key),color:({win:'#176346',tie:'#435269',loss:'#943832',undetermined:'#875015'})[key]}));
const executionCategories=[{key:'completed',label:'Completed',color:'#176346'},{key:'failed',label:'Failed',color:'#b42318'},{key:'interrupted',label:'Stopped',color:'#1d4ed8'},{key:'other',label:'Other / not started',color:'#64748b'}];
function stackedChart(title,rows,categories,unit,note){
  const panel=node('div',undefined,'chart-panel');panel.append(node('h3',title));
  const legend=node('div',undefined,'chart-legend');for(const category of categories){const key=node('span',undefined,'chart-key'),swatch=benchSvg('svg',{viewBox:'0 0 9 9',class:'chart-swatch','aria-hidden':'true'});swatch.append(benchSvg('rect',{width:9,height:9,fill:category.color}));key.append(swatch,document.createTextNode(category.label));legend.append(key);}panel.append(legend);
  if(!rows.length){panel.append(node('p','No recorded data under the selected filters.','chart-empty'));return panel;}
  const scale=view.countScale(Math.max(0,...rows.map(row=>categories.reduce((total,category)=>total+(row.counts[category.key]||0),0)))),maximum=scale.maximum;
  for(const row of rows){
    const item=node('div',undefined,'chart-row'),total=categories.reduce((sum,category)=>sum+(row.counts[category.key]||0),0),heading=node('div',undefined,'chart-row-label');if(row.key)item.dataset.key=row.key;heading.append(node('strong',row.label),node('span',row.totalLabel||total.toLocaleString()+' '+unit,'chart-row-total'));item.append(heading);
    if(row.identity)item.append(node('code',row.identity,'chart-identity'));if(row.condition)item.append(node('code','Condition '+row.condition,'chart-identity'));
    const values=categories.map(category=>category.label+': '+(row.counts[category.key]||0)).join('; '),svg=benchSvg('svg',{class:'chart-plot',role:'img','aria-label':row.label+' · '+values,'data-total':total,'data-maximum':maximum});svg.append(benchSvg('rect',{x:0,y:3,width:'100%',height:22,fill:'#e8edf2',rx:2}));let x=0;
    for(const category of categories){const value=row.counts[category.key]||0,width=value/maximum*100,rect=benchSvg('rect',{x:x+'%',y:3,width:width+'%',height:22,fill:category.color,'data-category':category.key,'data-count':value});rect.append(benchSvg('title',{},row.label+' · '+category.label+': '+value));svg.append(rect);if(width>=(value.toLocaleString().length*7+6)/240*100)svg.append(benchSvg('text',{x:(x+width/2)+'%',y:18,'text-anchor':'middle',fill:'#fff'},value.toLocaleString()));x+=width;}
    item.append(svg,node('span',values,'sr-only'));panel.append(item);
  }
  const axis=node('div',undefined,'chart-axis');for(const value of scale.ticks){const tick=node('span',value.toLocaleString('en',{notation:'compact',maximumFractionDigits:1}));tick.title=value.toLocaleString('en');axis.append(tick);}panel.append(axis,node('p',note,'chart-note'));return panel;
}
function renderCharts(){
  const projected=view.chartData(state),rank=arm=>arm===state.baseline?0:arm==='candidate'?1:2,execution=projected.execution.sort((a,b)=>rank(a.arm)-rank(b.arm)).map(row=>({key:row.arm,label:roleLabel(row.arm),identity:armLabel(row.arm),counts:{...row.status_counts,other:Object.entries(row.status_counts).filter(([key])=>!['completed','failed','interrupted'].includes(key)).reduce((total,[,count])=>total+count,0)}}));
  const comparisons=projected.comparisons.map(row=>{const trial=view.select(state).trials.find(t=>t.case_id===row.case_id&&((view.cohorts.get(t.cohort_id)||{}).case_fingerprint||t.case_id)===row.case_fingerprint);return {key:row.case_fingerprint,label:trial?caseLabel(trial):row.case_id,counts:row.counts};});
  put('overview-charts',stackedChart('Runs by tested version',execution,executionCategories,'runs','Absolute run counts on one shared scale; execution status is separate from quality.'),stackedChart('Comparison by case',comparisons,comparisonCategories,'pairs','Candidate direction. Unreviewed or mismatched comparisons remain in Not enough evidence.'));
  const ratings=projected.ratings.sort((a,b)=>a.case_id.localeCompare(b.case_id)||rank(a.arm)-rank(b.arm)||a.cohort_id.localeCompare(b.cohort_id)).map(row=>{const context=view.cohorts.get(row.cohort_id)||{},trial=view.select(state).trials.find(t=>t.case_id===row.case_id&&((view.cohorts.get(t.cohort_id)||{}).case_fingerprint||t.case_id)===(context.case_fingerprint||row.case_id));return {key:row.cohort_id,label:(trial?caseLabel(trial):row.case_id)+' · '+roleLabel(row.arm),identity:armLabel(row.arm),condition:row.cohort_id,counts:row.score_counts};});
  put('rating-charts',stackedChart('Requirement ratings by evaluated condition',ratings,ratingCategories,'ratings','Conditions stay separate. Dependent ordinal counts are not an overall score; absent reviews have no row.'));
  const labels={input_tokens:'Input tokens',cached_input_tokens:'Cached input tokens',uncached_input_tokens:'Uncached input tokens',output_tokens:'Output tokens'},tokens=projected.tokens.filter(row=>row.value!==null).map(row=>({key:row.field,label:labels[row.field],counts:{tokens:row.value},totalLabel:row.value.toLocaleString()+' · '+row.known+' / '+row.observed_turns+' recorded turns'}));
  const tokenChart=stackedChart('Known token subtotals',tokens,[{key:'tokens',label:'Tokens',color:'#245877'}],'tokens','Each row states its observation coverage. Cached and uncached input are components of total input; do not add all rows. Shell commands are a different unit and remain in the table.');
  const missing=projected.tokens.filter(row=>row.value===null);if(missing.length)tokenChart.append(node('p','Not recorded: '+missing.map(row=>labels[row.field]).join(', '),'chart-note'));put('usage-chart',tokenChart);
}
"""
